// Prova somente de leitura do exemplo com o racional de medição (janelas) e de registro (CRM).
// Só lê o arquivo do exemplo e imprime texto. Não grava nada.
const fs = require("fs");
const vm = require("vm");
const arq = require("path").join(__dirname, "..", "exemplo", "Aceleracao-365-Exemplo-Maturidade-Geracao-de-Leads.html");
const html = fs.readFileSync(arq, "utf8");
const codigo = html.slice(html.indexOf("<script>") + 8, html.lastIndexOf("</script>"));

// "hoje" fixa a data do dia dentro do exemplo, como [ano, mês de 0 a 11, dia], para a prova não depender de quando roda.
function bruto(rota, estado, hoje) {
  // Na prova, quem marcou que todo contato entra no CRM passou no teste, salvo quando o caso diz outra coisa.
  if (estado && estado.rn) estado = Object.assign({}, estado, { rn: Object.assign({ teste5: "ok", prox6: "todos", crit7: "ambos", rel8: "completo", dec8: "mes" }, estado.rn) });
  const el = () => ({ setAttribute() {}, focus() {}, appendChild() {}, hidden: true, innerHTML: "", textContent: "", className: "", id: "", scrollIntoView() {} });
  const main = el();
  main.addEventListener = () => {};
  const fixos = { main: main, "folha-t": el(), "folha-c": el(), "folha-ok": el() };
  const ctx = { document: { getElementById: (id) => fixos[id] || null, createElement: el, body: { appendChild() {} }, addEventListener() {}, contains: () => false }, window: { scrollTo() {}, addEventListener() {} }, location: { hash: rota + (estado ? "?e=" + encodeURIComponent(JSON.stringify(estado)) : "") }, history: { pushState() {} }, console };
  if (hoje) ctx.Date = class extends Date { constructor(...a) { if (a.length) super(...a); else super(hoje[0], hoje[1], hoje[2]); } };
  vm.createContext(ctx);
  vm.runInContext(codigo, ctx);
  return main.innerHTML;
}
const texto = (h) => h.replace(/<button type="button" class="q"[^>]*>\?<\/button>/g, "").replace(/<\/(p|h1|h2|h3|li|div|button|label)>/g, "\n").replace(/<[^>]+>/g, "").replace(/\n\s*\n+/g, "\n").trim();
const abrir = (rota, estado) => texto(bruto(rota, estado));
const linha = (t, ini, n) => { const l = t.split("\n"), i = l.findIndex((x) => x.indexOf(ini) !== -1); return i < 0 ? "(não achei: " + ini + ")" : l.slice(i, i + (n || 1)).join(" | "); };
const sep = (t) => console.log("\n=== " + t + " ===");
let falhas = 0, total = 0;
const confere = (ok, rot) => { total++; if (!ok) falhas++; console.log((ok ? "ok   " : "FALHA") + " " + rot); };

const R = { 2: 2, 4: 2, 5: 2, 6: 0, 7: 0, 8: 0 };
// A ficha do Google em dois estados: "viva" tem os três fatos em dia (de pé), e "parada" tem os três em falta (em parte).
const FICHA = { viva: { esc: "naopede", num: { pub: "mes", aval: "nenhuma", viram: 360, comp: "subiu", pct: 8 } }, parada: { esc: "pede", num: { pub: "antes", aval: "tem", viram: 360, comp: "subiu", pct: 8 } } };
// Na ficha do Google, a situação da Etapa 4 sai do teste da porta principal.
const portaDe = (resp) => (resp && resp[4] !== undefined ? { porta: "orientacoes", t_orientacoes: { 2: "certa", 1: "semfoto", 0: "errada", "-1": "nt" }[resp[4]] } : {});
const gmn = (tipo, resp, num, opc) => ({ pilar: "inbound", canal: "google-meu-negocio", esc: FICHA[tipo].esc, resp: resp, opc: opc || {}, num: Object.assign({}, FICHA[tipo].num, portaDe(resp), num || {}) });
const pil = (x) => ({ rn: { inbound: Object.assign({ o_contatos: "e", o_prontos: "e" }, x) }, ex: {} });
const est = (o) => Object.assign({ obj: "rn", ticket: 250, rn: { hoje: 18, meta: 30, o_hoje: "e" } }, o);
const passo = (t) => linha(t, "Seu Próximo Passo", 2);

sep("Janelas: cada número diz de quando é");
const e1 = abrir("#/d/1", est({}));
const e2 = abrir("#/d/2", est({ at: { pilar: "inbound", resp: { 2: 1 } }, pil: pil({ mes: 7 }) }));
const e5 = abrir("#/d/5", est({ at: gmn("viva", { 2: 2, 4: 2 }), pil: pil({ mes: 7 }) }));
const e3 = abrir("#/d/3", est({ at: { pilar: "outbound", canal: "ligacao", resp: { 2: 2, 3: 1 }, num: { m1: 40, m2: 6, o_m1: "e", o_m2: "e" } }, pil: { rn: { outbound: { mes: 2 } }, ex: {} } }));
console.log("Etapa 1: " + linha(e1, "Quantos Clientes Novos Você Conquista por Mês?", 2));
console.log("Etapa 2: " + linha(e2, "Você sabe por onde chegaram", 1));
console.log("Etapa 2: " + linha(e2, "Desses Clientes Novos por Mês", 2));
console.log("Etapa 5: " + linha(e5, "Quantos Contatos Novos Chegam por Mês", 2));
console.log("Etapa 3: " + linha(e3, "Ligações Feitas no Último Mês", 1));
confere(e1.indexOf("Média dos últimos três meses") !== -1, "Etapa 1 pede a média mensal dos últimos três meses");
confere(e2.indexOf("clientes novos dos últimos três meses") !== -1 && e2.indexOf("Você informou 18 por mês, na média dos últimos três meses") !== -1, "Etapa 2 usa a mesma amostra da Etapa 1");
confere(e5.indexOf("Média dos últimos três meses. Some todos os canais do Inbound") !== -1, "Etapa 5 pede a média mensal dos últimos três meses");
confere(e3.indexOf("Ligações Feitas no Último Mês") !== -1, "A medida do canal é do último mês");

sep("Registro: o CRM é o padrão das etapas de registro");
console.log(linha(e5, "O que acontece com o contato", 6));
confere(e5.indexOf("Todo contato entra no CRM, com origem e responsável") !== -1 && e5.indexOf("Tenho CRM, mas nem todo contato entra") !== -1, "Etapa 5: de pé é o CRM com rotina, e CRM sem rotina é em parte");
const n5 = (opc, v) => abrir("#/d/fim", est({ at: gmn("viva", { 2: 2, 4: 2, 5: v, 6: 0, 7: 0, 8: 0 }, null, { 5: opc }), pil: pil({ mes: 7, contatos: 20, prontos: 8 }) }));
console.log("CRM sem rotina   -> " + linha(n5(2, 1), "Nível", 1) + " || " + passo(n5(2, 1)));
console.log("CRM com rotina   -> " + linha(n5(3, 2), "Nível", 1) + " || " + passo(n5(3, 2)));
confere(n5(2, 1).indexOf("Nível 3: Presença") !== -1 && n5(3, 2).indexOf("Nível 4: Captação") !== -1, "CRM sem rotina não sobe o nível; CRM com rotina sobe");
const lei5 = abrir("#/d/5", est({ at: gmn("viva", { 2: 2, 4: 2, 5: 1 }, null, { 5: 2 }), pil: pil({ mes: 7 }) }));
confere(lei5.indexOf("O CRM existe, mas não recebe todos os contatos") !== -1, "A leitura fala da opção escolhida, e não de um degrau genérico");
const n2 = (opc) => abrir("#/d/fim", est({ at: gmn("viva", { 2: 2, 4: 2, 5: 0, 6: 0, 7: 0, 8: 0 }, null, { 2: opc }), pil: pil({ mes: 7 }) }));
console.log("Etapa 2 com levantamento -> " + linha(n2(2), "Nível", 1));
console.log("Etapa 2 com CRM          -> " + linha(n2(3), "Nível", 1));
confere(n2(2).indexOf("Nível 3: Presença") !== -1 && n2(3).indexOf("Nível 3: Presença") !== -1, "Na Etapa 2, o levantamento e o CRM valem como de pé");
confere(e2.indexOf("Tenho o levantamento, cliente por cliente") !== -1 && e2.indexOf("Tiro do CRM a origem de cada cliente") !== -1 && e2.indexOf("Tenho anotado") === -1, "A resposta 'Tenho anotado' deu lugar ao levantamento e ao CRM");

sep("Mapa de origem: fecha com o total da Etapa 1");
console.log(linha(e2, "dos seus 18 clientes novos por mês", 1));
const cam = (p, c, esc, resp, num) => ({ obj: "rn", pilar: p, canal: c, esc: FICHA[esc] ? FICHA[esc].esc : esc, resp: resp, opc: {}, num: Object.assign({}, FICHA[esc] ? FICHA[esc].num : {}, FICHA[esc] ? portaDe(resp) : {}, num || {}) });
const final = (inb, out, sem) => abrir("#/d/final", { obj: "rn", ticket: 250, rn: { hoje: 18, meta: 30, o_hoje: "e", semOrigem: sem || null }, feitos: [cam("inbound", "google-meu-negocio", "viva", { 2: 2, 4: 2, 5: 2, 6: 0, 7: 0, 8: 0 }, { interacoes: 120, o_interacoes: "m" }), cam("outbound", "ligacao", null, { 2: 2, 3: 1, 4: 0, 5: 0, 6: 0, 7: 0, 8: 0 }, { m1: 40, m2: 6, o_m1: "e", o_m2: "e" })], pil: { rn: { inbound: { mes: inb }, outbound: { mes: out } }, ex: {} } });
const f1 = final(7, 1, 2), f2 = final(4, 6, 2), f3 = final(12, 10, 0);
console.log(linha(f1, "Inbound", 1) + " | " + linha(f1, "Não sei de onde veio", 1) + " | " + linha(f1, "Fora dos pilares percorridos", 1));
confere(f1.indexOf("7 de 18") !== -1 && f1.indexOf("Não sei de onde veio2 de 18") !== -1 && f1.indexOf("Fora dos pilares percorridos, por diferença8 de 18") !== -1, "O mapa mostra cada parte sobre o total de 18 e fecha a conta");
confere(e2.indexOf("7 dos seus 18 clientes novos por mês") !== -1, "A leitura da Etapa 2 usa o total da Etapa 1");
console.log(linha(f3, "a conta passou", 1));
confere(f3.indexOf("a conta passou dos 18 clientes novos por mês") !== -1, "Quando a soma passa do total, a tela avisa");

sep("A rota não muda por número");
const t2a = abrir("#/d/fim", est({ at: gmn("parada", R), pil: pil({ mes: 4, contatos: 20, prontos: 10 }) }));
const t2b = abrir("#/d/fim", est({ at: gmn("parada", R), pil: pil({ mes: 4, contatos: 20, prontos: 9 }) }));
confere(passo(t2a) === passo(t2b), "O próximo passo é o mesmo com 10 ou com 9 prontos: " + passo(t2a));
const d1 = [3, 4, 5].map((d) => passo(abrir("#/d/fim", est({ at: gmn("parada", R), pil: pil({ mes: d, contatos: 20, prontos: 16 }) }))));
confere(d1[0] === d1[1] && d1[1] === d1[2], "O próximo passo é o mesmo com 3, 4 ou 5 clientes por este caminho");
console.log("Origem 7 e 1: " + linha(f1, "Comece por", 1).slice(0, 70));
console.log("Origem 4 e 6: " + linha(f2, "Comece por", 1).slice(0, 70));
confere(linha(f1, "Comece por", 1) === linha(f2, "Comece por", 1), "A rota proposta não muda quando a origem muda");

sep("Conversão do caminho e retorno do canal: resultados da análise");
const t5 = abrir("#/d/fim", est({ rn: { hoje: 12, meta: 25, o_hoje: "e" }, at: { pilar: "inbound", canal: "meta-ads", esc: "roda", resp: { 2: 2, 4: 2, 5: 2, 6: 1, 7: 1, 8: 1 }, opc: {}, num: { invest: 3200, contatos: 400, o_invest: "m", o_contatos: "m" } }, pil: pil({ mes: 8, contatos: 400, prontos: 40 }) }));
console.log(linha(t5, "Conversão do caminho", 1)); console.log(linha(t5, "Ponto para o atendimento", 1)); console.log(linha(t5, "Custo por contato", 1));
confere(t5.indexOf("Conversão do caminho: de contato a SQL, 1 em cada 10; de SQL a cliente, 2 em cada 10.") !== -1, "A conversão do caminho aparece, com os três números da mesma janela");
confere(t5.indexOf("É o relacionamento que recupera") === -1 && t5.indexOf("Ponto para o atendimento") !== -1, "A perda continua como ponto para o atendimento, sem causa afirmada");
console.log(linha(e3, "Retorno do canal", 1));
confere(e3.indexOf("Retorno do canal: 2 em cada 10.") !== -1, "O retorno do canal aparece: 6 conversas em 40 ligações");
const t3 = abrir("#/d/fim", est({ at: gmn("parada", { 2: 2, 4: 2, 5: 2, 6: 2, 7: 2, 8: 2 }, { interacoes: 400 }), pil: pil({ mes: 8, contatos: 40, prontos: 30 }) }));
confere(t3.indexOf("Depois dela, já estão de pé as Etapas 4 (Conversão), 5 (Lead), 6 (Relacionamento), 7 (Lead Qualificado), 8 (Medir e Ajustar)") !== -1, "A tela continua dizendo onde a rota quebra");
const t6 = abrir("#/d/fim", est({ rn: { hoje: 1, meta: 2, o_hoje: "m" }, at: { pilar: "outbound", canal: "abm", resp: { 2: 1, 3: 1, 4: 1, 5: 2, 6: 1, 7: 1, 8: 0 }, opc: {}, num: { m1: 12, m2: 3, o_m1: "m", o_m2: "m" } }, pil: { rn: { outbound: { mes: 1, contatos: 9, prontos: 4, o_contatos: "e", o_prontos: "e" } }, ex: {} } }));
console.log(linha(t6, "Origem dos Clientes", 3));
confere(t6.indexOf("cerca de") === -1 && t6.indexOf("1 de 1") !== -1, "Com um cliente por mês, a tela mostra 1 de 1, sem estimativa");

sep("Cruzamento entre estrutura e resultado");
const cruz = (alto, hoje) => linha(abrir("#/d/final", { obj: "rn", ticket: 250, rn: { hoje: hoje, meta: 30, o_hoje: "e" }, feitos: [cam("inbound", "google-meu-negocio", "viva", alto ? { 2: 2, 4: 2, 5: 2, 6: 0, 7: 0, 8: 0 } : { 2: 2, 4: 0, 5: 0, 6: 0, 7: 0, 8: 0 }, { interacoes: 120, o_interacoes: "m" })], pil: { rn: { inbound: { mes: 4 } }, ex: {} } }), "Leitura das duas medidas", 1).slice(0, 62);
const c = [cruz(true, 30), cruz(true, 18), cruz(false, 30), cruz(false, 18)];
c.forEach((x) => console.log(x));
confere(c[0].indexOf("Estrutura com Resultado") !== -1 && c[1].indexOf("Estrutura sem Resultado") !== -1 && c[2].indexOf("Resultado sem Estrutura") !== -1 && c[3].indexOf("Começo") !== -1, "As quatro leituras continuam certas");

sep("Todos os canais");
const pilares = { inbound: ["google-ads", "meta-ads", "seo", "geo", "google-meu-negocio", "avaliacoes-google", "oferta-de-entrada", "ponto-fisico"], outbound: ["disparo-email", "disparo-whatsapp", "ligacao", "abordagem-redes", "porta-em-porta", "abm", "feiras-eventos"], branding: ["blog", "podcast", "youtube", "instagram", "linkedin-dono", "comunidades", "imprensa-premios"], indicacao: ["indicacao-clientes", "programa-indicacao", "parceiros", "revendas", "marketplaces"], base: ["venda-adicional", "venda-cruzada", "recompra", "reativacao", "pos-venda"] };
let okc = 0, tot = 0, med = 0, trava = 0, ret = 0;
Object.keys(pilares).forEach((p) => pilares[p].forEach((k) => {
  const ex = p === "base", base = ex ? { obj: "ex", ticket: 250, ex: { hoje: 6, meta: 10, o_hoje: "e" } } : { obj: "rn", ticket: 250, rn: { hoje: 18, meta: 30, o_hoje: "e" } };
  tot++;
  try {
    const t = abrir("#/d/3", Object.assign({}, base, { at: { pilar: p, canal: k, resp: { 2: 2, 3: 2 }, num: { m1: 10, m2: 2 } }, pil: { rn: {}, ex: {} } }));
    if (t.indexOf("Mais ou menos") === -1) okc++;
    if (t.indexOf("De onde vem este número?") !== -1) { med++; if (t.indexOf("Próxima etapa") === -1 && t.indexOf("Para seguir, marque de onde vem cada número") !== -1) trava++; }
    if (t.indexOf("Retorno do canal") !== -1) ret++;
  } catch (e) { console.log("ERRO no canal " + k + ": " + e.message); }
}));
console.log(okc + " de " + tot + " canais sem escala de opinião | " + med + " com medida própria | " + trava + " exigem a marca de origem e avisam | " + ret + " mostram o retorno do canal");
confere(okc === 32 && med === 21 && trava === 21 && ret === 12, "Os 32 canais abrem, 21 pedem medida com marca de origem e 12 mostram o retorno");

sep("Toda tela tem saída");
const telas = [["Jornada", "#/", null], ["Início", "#/inicio", null], ["Biblioteca", "#/biblioteca", null]];
for (let n = 1; n <= 8; n++) telas.push(["Etapa " + n, "#/d/" + n, est({ at: gmn("viva", { 2: 2, 4: 2, 5: 2, 6: 2, 7: 2, 8: 2 }), pil: pil({ mes: 7, contatos: 20, prontos: 8 }) })]);
telas.push(["Fim do Caminho", "#/d/fim", est({ at: gmn("viva", R), pil: pil({ mes: 7, contatos: 20, prontos: 8 }) })]);
telas.push(["Fluxo Adequado", "#/d/final", est({ feitos: [cam("inbound", "google-meu-negocio", "viva", R, { interacoes: 120, o_interacoes: "m" })], pil: pil({ mes: 7 }) })]);
let semSaida = 0;
telas.forEach((x) => { const h = bruto(x[1], x[2]); if (!(h.match(/data-go=|data-acao=/g) || []).length) { semSaida++; console.log("SEM SAÍDA: " + x[0]); } });
confere(semSaida === 0, telas.length + " telas conferidas, nenhuma sem saída");

sep("Expansão");
const exFim = abrir("#/d/fim", { obj: "ex", ticket: 250, ex: { hoje: 6, meta: 10, o_hoje: "m" }, at: { pilar: "base", canal: "recompra", resp: { 2: 2, 3: 2, 4: 1, 5: 0, 6: 0, 7: 0, 8: 0 }, opc: { 2: 3 }, num: { m1: 30, m2: 4, o_m1: "m", o_m2: "m" } }, pil: { rn: {}, ex: { base: { base: 180, contatos: 12, prontos: 8, o_base: "e", o_contatos: "e", o_prontos: "e" } } } });
const ex2 = abrir("#/d/2", { obj: "ex", ticket: 250, ex: { hoje: 6, meta: 10, o_hoje: "m" }, at: { pilar: "base", resp: {} }, pil: { rn: {}, ex: {} } });
console.log(linha(exFim, "Nível", 1) + " || " + passo(exFim)); console.log(linha(exFim, "Conversão do caminho", 1)); console.log(linha(ex2, "Onde estão os contatos", 6));
confere(exFim.indexOf("Nível 3: Presença") !== -1 && exFim.indexOf("Etapa 4: Conversão") !== -1 && exFim.indexOf("de resposta a pronto, 7 em cada 10; de pronto a venda, 8 em cada 10") !== -1, "Na Expansão, nível, próximo passo e conversão funcionam");
confere(ex2.indexOf("Estão no CRM, com contato e data da última compra") !== -1, "Na Expansão, a base de clientes de pé é a que está no CRM");

sep("Coerência entre o número mostrado e o ponto para o atendimento");
const c9 = abrir("#/d/fim", est({ at: gmn("parada", R), pil: pil({ mes: 7, contatos: 20, prontos: 9 }) }));
const c8 = abrir("#/d/fim", est({ at: gmn("parada", R), pil: pil({ mes: 7, contatos: 20, prontos: 8 }) }));
const aviso = (t) => (t.indexOf("Mais da metade dos contatos") !== -1 ? "levanta o ponto" : "não levanta o ponto");
console.log("9 prontos de 20 contatos -> " + linha(c9, "Conversão do caminho", 1) + " || " + aviso(c9));
console.log("8 prontos de 20 contatos -> " + linha(c8, "Conversão do caminho", 1) + " || " + aviso(c8));
confere(c9.indexOf("de contato a SQL, 5 em cada 10") !== -1 && c9.indexOf("Mais da metade dos contatos") === -1, "Com 5 em cada 10, a tela não diz que mais da metade se perde");
confere(c8.indexOf("de contato a SQL, 4 em cada 10") !== -1 && c8.indexOf("Mais da metade dos contatos") !== -1, "Com 4 em cada 10, a tela levanta o ponto para o atendimento");

sep("Ficha do Google: três fatos conferidos, e a procura lida à parte");
const g3 = (esc, num, resp) => ({ pilar: "inbound", canal: "google-meu-negocio", esc: esc, resp: resp || { 2: 2 }, opc: { 2: 2 }, num: Object.assign({}, portaDe(resp), num || {}) });
const tela3 = (esc, num, hoje) => texto(bruto("#/d/3", est({ at: g3(esc, num), pil: pil({ mes: 7 }) }), hoje));
const fim3 = (esc, num) => abrir("#/d/fim", est({ at: g3(esc, num, { 2: 2, 4: 2, 5: 0, 6: 0, 7: 0, 8: 0 }), pil: pil({ mes: 7 }) }));
const com = (a, b) => Object.assign({}, a, b);
const P360 = { viram: 360, comp: "subiu", pct: 8 };
const EM_FALTA = { pub: "antes", aval: "tem" }, EM_DIA = { pub: "mes", aval: "nenhuma" };
const gPersona = tela3("pede", com(EM_FALTA, P360), [2026, 10, 6]);
const gDePe = tela3("naopede", com(EM_DIA, P360));
console.log(linha(gPersona, "Dos três pontos da ficha", 1)); console.log(linha(gPersona, "A ficha foi vista por", 1)); console.log(linha(gPersona, "Por onde começar", 1)); console.log(linha(gPersona, "Hoje são", 1));
confere(["O Google ainda pede algo para completar o seu perfil?", "Quando foi a sua última publicação na ficha?", "Alguma avaliação está sem resposta?", "Quantas Pessoas Viram a Ficha nos Três Últimos Meses Completos?", "Sobre o Ano Passado", "Percentual"].every((x) => gPersona.indexOf(x) !== -1), "A tela traz as cinco perguntas, e o campo do percentual abre depois de dizer que subiu");
confere(gPersona.indexOf("Dos três pontos da ficha, nenhum está em dia. Falta completar o que o Google pede, publicar de novo e responder às avaliações.") !== -1 && gPersona.indexOf("Por onde começar: Clique em Força do Perfil e preencha o que o Google pede.") !== -1, "Com os três fatos em falta, a leitura diz o que falta e começa pelo primeiro");
confere(gDePe.indexOf("A ficha está de pé: sem pendência no Google, com publicação no último mês e sem avaliação por responder.") !== -1 && gDePe.indexOf("Por onde começar") === -1, "Com os três fatos em dia, a ficha está de pé e não há tarefa");
const nivel = (t) => linha(t, "Nível", 1);
const nv = { tres: nivel(fim3("naopede", com(EM_DIA, P360))), um: nivel(fim3("naopede", com({ pub: "antes", aval: "nenhuma" }, P360))), semAval: nivel(fim3("naopede", com({ pub: "mes", aval: "semaval" }, P360))), semFicha: nivel(fim3("semficha", {})), naoSei: nivel(fim3("ns", com(EM_DIA, P360))) };
console.log("Três em dia -> " + nv.tres + " | um em falta -> " + nv.um + " | sem avaliações -> " + nv.semAval + " | sem ficha -> " + nv.semFicha + " | um por conferir -> " + nv.naoSei);
